mapper.select:
/* selectBuyerMdAmUserRegRequestReceiptList */ SELECT ROWNUM ROWM, /* 순번 */ L.USER_ID, /* 사용자 ID */ L.COM_CODE, /* 고객사코드 */ (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = L.COM_CODE) AS BUYER_NAME, /* 고객사명 */ (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = L.COM_CODE) AS COM_NAME_LOC, /* 고객사명 */ L.USER_NAME_LOC, /* 사용자 이름 */ L.PHONE_NUMBER, /* 핸드폰번호 */ L.EMAIL, /* 이메일 */ L.DEPARTMENT, /* 부서코드 */ (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) DEPT_NAME, /* 부서명 */ L.STATUS, (SELECT IL.USER_NAME_LOC FROM ICOMLUSR IL WHERE IL.USER_ID = L.CONFIRM_USER_ID) AS CONFIRM_USER_NAME, L.REJECT_REASON /* 상태 */ FROM ICOMLUSR L WHERE L.USER_TYPE='U' AND L.CHANGE_USER_TYPE='U'
AND L.STATUS = #{st_target_status}
AND TRIM(L.REJECT_REASON) IS NOT NULL AND REG_DATE >= '20260828' /*개발시작 날짜 이후 데이터만 나오도록*/
AND L.STATUS = 'S'
AND L.COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND L.COM_CODE = #{st_buyer_select}
AND L.COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND L.COM_CODE = #{SESSION_BUYER_CODE}
AND L.USER_NAME_LOC LIKE '%'||#{st_search_user_name}||'%'
AND L.DEPARTMENT = #{st_btoa_user_dept_code}
AND (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = L.COM_CODE AND TYPE='C001' AND CODE = L.DEPARTMENT) LIKE '%'||#{st_btoa_user_dept_name}||'%'
ORDER BY L.REG_DATE DESC

mapper.update:

UPDATE ICOMLUSR
SET
	STATUS      = 'C',
	BEGIN_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	CONFIRM_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	USER_TYPE = CHANGE_USER_TYPE,
	CONFIRM_USER_ID = #{st_user_id}
WHERE USER_ID = #{st_change_user_id}




		AND	COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')




		AND COM_CODE = #{st_com_code}


UPDATE ICOMLUSR
SET
	STATUS      = 'D',
	REJECT_REASON = #{st_reject_reason},
	CONFIRM_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	CONFIRM_USER_ID = #{st_user_id}
WHERE USER_ID = #{st_change_user_id}




		AND	COM_CODE IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')




		AND COM_CODE = #{st_com_code}
